use vstd::prelude::*;
use vstd::{vec, Vec};
use builtin::*;
use builtin::seq::Seq;

verus! {

    // Specification function to count how many participants in the given sequence can attend 
    // at least k more sessions, i.e., (5 - attendance_count) >= k.
    //
    // participations: a sequence of non-negative integers each in [0..=5]
    // k: integer in [0..=5]
    //
    // Returns the count of eligible participants.
    spec fn count_eligible(participations: Seq<int>, k: int) -> int {
        // Count elements p in participations where (5 - p) >= k.
        // Equivalent to p <= 5 - k
        participations.iter().filter(|&p| *p <= 5 - k).count() as int
    }


    // Main function: given n, k, and participations vector,
    // return the maximum number of teams of 3 eligible participants.
    //
    // n: number of participants to consider (could be less or more than participations.len())
    // k: minimum additional sessions participants must be able to attend
    // participations: vector of attendance counts per participant (each 0..=5)
    //
    // Returns the integer division of eligible participants count by 3.
    fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8
        requires k <= 5
        requires forall |i: usize| i < participations.len() ==> participations[i] <= 5
        ensures |result: u8| {
            // The return value equals floor(count_eligible of relevant participants / 3)
            let len = (n as usize).min(participations.len());
            let seq_part = Seq::<int>::from_slice(&participations[..len]).map(|x| x as int);
            result as int == count_eligible(seq_part, k as int) / 3
        }
    {
        let len = (n as usize).min(participations.len());
        let mut eligible_count: u8 = 0;
        let mut i: usize = 0;

        // loop to count eligible participants among the first `len`
        while i < len
            invariant i <= len
            invariant eligible_count <= i as u8
            invariant forall |j: usize| j < i ==> participations[j] <= 5
            decreases len - i
        {
            let attendance = participations[i];
            if 5 - attendance >= k {
                eligible_count = eligible_count + 1;
            }
            i = i + 1;
        }

        // Return maximum number of teams of size 3
        eligible_count / 3
    }

}